1	import { Component, OnInit, inject } from '@angular/core';
2	import { CommonModule } from '@angular/common';
3	import { Router, RouterLink } from '@angular/router';
4	import { FormsModule } from '@angular/forms';
5	
6	import { CompanyStateService } from '../../../core/state/company-state.service';
7	import { CompanyApiService } from '../../../core/api/company-api.service';
8	import { DomainApiService } from '../../../core/api/domain-api.service';
9	import { RequestApiService } from '../../../core/api/request-api.service';
10	import { ProductApiService } from '../../../core/api/product-api.service';
11	import { CompanyUserApiService } from '../../../core/api/company-user-api.service';
12	import { ToastService } from '../../../core/services/toast.service';
13	import { DialogService } from '../../../core/services/dialog.service';
14	
15	import { Company } from '../../../shared/models/company.model';
16	import { Request, RequestStatus } from '../../../shared/models/request.model';
17	import { Product, SchedulePeriodType } from '../../../shared/models/product.model';
18	import { CompanyUser, CompanyUserType, CompanyUserRequestDto } from '../../../shared/models/company-user.model';
19	import { RequestDto, DomainItemDto, CompanyUpdateDto } from '../../../shared/models/dtos.model';
20	
21	type CompanyTab = 'requests' | 'products' | 'users';
22	type ModalMode =
23	  | 'none'
24	  | 'companyView'
25	  | 'companyEdit'
26	  | 'requestView'
27	  | 'requestAdd'
28	  | 'requestEdit'
29	  | 'productView'
30	  | 'productAdd'
31	  | 'productEdit'
32	  | 'userView'
33	  | 'userAdd'
34	  | 'userEdit';
35	
36	@Component({
37	  selector: 'app-company-dashboard',
38	  standalone: true,
39	  imports: [CommonModule, FormsModule, RouterLink],
40	  templateUrl: './company-dashboard.component.html',
41	  styleUrls: ['./company-dashboard.component.scss']
42	})
43	export class CompanyDashboardComponent implements OnInit {
44	  company: Company | null = null;
45	
46	  activeTab: CompanyTab = 'requests';
47	
48	
49	  // Domain lookups (for Legal Form / Economic Activity display + dropdowns)
50	  legalForms: DomainItemDto[] = [];
51	  economicActivities: DomainItemDto[] = [];
52	
53	  // Company detail form (mirrors the registration form, minus credentials).
54	  companyForm: {
55	    name: string;
56	    taxCode: string;
57	    address: string;
58	    legalForm: number | null;
59	    economicActivity: number | null;
60	    mail: string;
61	    phone: string;
62	    bankAccountIban: string;
63	    bankAccountName: string;
64	    bankName: string;
65	  } = {
66	    name: '',
67	    taxCode: '',
68	    address: '',
69	    legalForm: null,
70	    economicActivity: null,
71	    mail: '',
72	    phone: '',
73	    bankAccountIban: '',
74	    bankAccountName: '',
75	    bankName: ''
76	  };
77	
78	  // Requests tab state
79	  requests: Request[] = [];
80	  requestsLoading = false;
81	  selectedRequest: Request | null = null;
82	
83	  // Products tab state
84	  products: Product[] = [];
85	  productsLoading = false;
86	  selectedProduct: Product | null = null;
87	
88	  // Products query state (API does not expose CompanyId filter; we filter client-side)
89	  productSearch = '';
90	  productSkip = 0;
91	  productTake = 200;
92	
93	  // Modal state
94	  modalOpen = false;
95	  modalMode: ModalMode = 'none';
96	  modalTitle = '';
97	  modalLoading = false;
98	  modalError = '';
99	
100	  modalRequest: Request | null = null;
101	  modalProduct: Product | null = null;
102	  modalUser: CompanyUser | null = null;
103	
104	  // Forms
105	  requestForm: RequestDto = { companyId: 0, productId: 0, serviceTokenCount: 1 };
106	  requestFormProductIdManual: number | null = null;
107	
108	  productForm: Product = {
109	    id: 0,
110	    companyId: 0,
111	    name: '',
112	    serviceCount: 0,
113	    price: 0,
114	    term: null,
115	    scheduleType: { periodType: SchedulePeriodType.None, periodNumber: null }
116	  };
117	
118	  // Users tab state
119	  users: CompanyUser[] = [];
120	  usersLoading = false;
121	  selectedUser: CompanyUser | null = null;
122	
123	  // Users query state (GetAllUsers does not filter by CompanyId; we filter client-side)
124	  userSearch = '';
125	  userSkip = 0;
126	  userTake = 200;
127	
128	  // Expose the enum to the template
129	  CompanyUserType = CompanyUserType;
130	
131	  userForm: CompanyUserRequestDto = {
132	    userType: CompanyUserType.Other,
133	    companyId: 0,
134	    userName: '',
135	    password: ''
136	  };
137	
138	  // Pictogram state
139	  pictogramFile: File | null = null;
140	  pictogramPreviewUrl: string | null = null;
141	  pictogramExistsOnServer = false;
142	
143	  private toast = inject(ToastService);
144	  private dialog = inject(DialogService);
145	
146	  constructor(
147	    private router: Router,
148	    private companyState: CompanyStateService,
149	    private companyApi: CompanyApiService,
150	    private domainApi: DomainApiService,
151	    private requestApi: RequestApiService,
152	    public productApi: ProductApiService,
153	    public companyUserApi: CompanyUserApiService
154	  ) {}
155	
156	  ngOnInit(): void {
157	    this.company = this.companyState.company;
158	
159	    if (!this.company) {
160	      this.router.navigate(['/login']);
161	      return;
162	    }
163	
164	    this.loadDomains();
165	    this.loadRequests();
166	    this.reloadProducts();
167	    this.reloadUsers();
168	  }
169	
170	  setTab(tab: CompanyTab) {
171	    this.activeTab = tab;
172	  }
173	
174	  // -----------------------------
175	  // Domain lookups
176	  // -----------------------------
177	  private loadDomains() {
178	    this.domainApi.getLegalForms().subscribe({
179	      next: items => (this.legalForms = items ?? []),
180	      error: err => console.error('Failed to load legal forms', err)
181	    });
182	    this.domainApi.getEconomicActivities().subscribe({
183	      next: items => (this.economicActivities = items ?? []),
184	      error: err => console.error('Failed to load economic activities', err)
185	    });
186	  }
187	
188	  legalFormName(id: number | null | undefined): string {
189	    if (id == null) return '-';
190	    return this.legalForms.find(x => x.id === id)?.name ?? `#${id}`;
191	  }
192	
193	  economicActivityName(id: number | null | undefined): string {
194	    if (id == null) return '-';
195	    return this.economicActivities.find(x => x.id === id)?.name ?? `#${id}`;
196	  }
197	
198	  // -----------------------------
199	  // Company details (View / Edit)
200	  // -----------------------------
201	  private fillCompanyForm() {
202	    if (!this.company) return;
203	    this.companyForm = {
204	      name: this.company.name,
205	      taxCode: this.company.taxCode,
206	      address: this.company.address,
207	      legalForm: this.company.legalForm,
208	      economicActivity: this.company.economicActivity,
209	      mail: this.company.mail,
210	      phone: this.company.phone,
211	      // Read shape: bank account is nested under the company (GetById includes it).
212	      bankAccountIban: this.company.bankAccount?.iban ?? '',
213	      bankAccountName: this.company.bankAccount?.beneficiaryName ?? '',
214	      bankName: this.company.bankAccount?.bankName ?? ''
215	    };
216	  }
217	
218	  onCompanyView() {
219	    if (!this.company) return;
220	    this.fillCompanyForm();
221	    this.openModal('companyView', 'Company details');
222	  }
223	
224	  onCompanyEdit() {
225	    if (!this.company) return;
226	    this.fillCompanyForm();
227	    this.openModal('companyEdit', 'Edit company');
228	  }
229	
230	  submitCompanyEdit() {
231	    if (!this.company) return;
232	
233	    if (this.companyForm.legalForm == null || this.companyForm.economicActivity == null) {
234	      this.modalError = 'Please select a legal form and an economic activity.';
235	      return;
236	    }
237	
238	    const payload: CompanyUpdateDto = {
239	      ...this.company,
240	      name: this.companyForm.name,
241	      taxCode: this.companyForm.taxCode,
242	      address: this.companyForm.address,
243	      legalForm: this.companyForm.legalForm,
244	      economicActivity: this.companyForm.economicActivity,
245	      mail: this.companyForm.mail,
246	      phone: this.companyForm.phone,
247	      // Write shape: the API binds onto CompanyRequestDto, so the bank account is
248	      // sent flat. An empty IBAN tells the API to clear the stored account.
249	      bankAccountIban: this.companyForm.bankAccountIban?.trim() ?? '',
250	      bankAccountName: this.companyForm.bankAccountName?.trim() ?? '',
251	      bankName: this.companyForm.bankName?.trim() ?? ''
252	    };
253	
254	    this.modalLoading = true;
255	    this.modalError = '';
256	
257	    this.companyApi.updateCompany(this.company.id, this.company.rowVersion, payload).subscribe({
258	      next: _ => {
259	        // Refresh from the server to pick up the new rowVersion and any server-side changes.
260	        this.companyApi.getById(this.company!.id).subscribe({
261	          next: fresh => {
262	            this.company = fresh;
263	            this.companyState.company = fresh;
264	            this.modalLoading = false;
265	            this.closeModal();
266	            this.toast.success('Company updated successfully.');
267	          },
268	          error: _err => {
269	            this.modalLoading = false;
270	            this.closeModal();
271	            this.toast.success('Company updated. Reload to see the latest values.');
272	          }
273	        });
274	      },
275	      error: err => {
276	        this.modalLoading = false;
277	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
278	        this.toast.error(message);
279	      }
280	    });
281	  }
282	
283	  // -----------------------------
284	  // Requests
285	  // -----------------------------
286	  loadRequests(silent = false) {
287	    if (!this.company) return;
288	
289	    this.requestsLoading = true;
290	    this.selectedRequest = null;
291	
292	    this.requestApi.getAll(this.company.id, RequestStatus.None).subscribe({
293	      next: data => {
294	        this.requests = data ?? [];
295	        this.requestsLoading = false;
296	      },
297	      error: err => {
298	        console.error(err);
299	        this.requestsLoading = false;
300	        if (!silent) {
301	          this.toast.errorWithRetry(
302	            'Failed to load requests. Please check your connection.',
303	            () => this.loadRequests()
304	          );
305	        }
306	      }
307	    });
308	  }
309	
310	  selectRequest(r: Request) {
311	    this.selectedRequest = r;
312	  }
313	
314	  onRequestView() {
315	    if (!this.selectedRequest) return;
316	
317	    this.openModal('requestView', 'Request details');
318	    // We already have the request object from the grid; show it directly.
319	    this.modalRequest = { ...this.selectedRequest };
320	  }
321	
322	  onRequestAdd() {
323	    if (!this.company) return;
324	
325	    this.requestForm = { companyId: this.company.id, productId: 0, serviceTokenCount: 1 };
326	    this.requestFormProductIdManual = null;
327	    this.openModal('requestAdd', 'Add new request');
328	  }
329	
330	  submitRequestAdd() {
331	    if (!this.company) return;
332	
333	    const productId =
334	      (this.requestFormProductIdManual ?? 0) > 0 ? (this.requestFormProductIdManual as number) : this.requestForm.productId;
335	
336	    if (!productId || productId <= 0) {
337	      this.modalError = 'Please select or enter a valid Product Id.';
338	      return;
339	    }
340	
341	    const dto: RequestDto = { companyId: this.company.id, productId, serviceTokenCount: this.requestForm.serviceTokenCount };
342	
343	    this.modalLoading = true;
344	    this.modalError = '';
345	
346	    this.requestApi.create(dto).subscribe({
347	      next: _ => {
348	        this.modalLoading = false;
349	        this.closeModal();
350	        this.loadRequests(true);
351	        this.toast.success('Request created successfully.');
352	      },
353	      error: err => {
354	        console.error(err);
355	        this.modalLoading = false;
356	
357	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
358	        this.toast.error(message);
359	      }
360	    });
361	  }
362	
363	  onRequestEdit() {
364	    if (!this.company || !this.selectedRequest) return;
365	
366	    this.requestForm = {
367	      companyId: this.company.id,
368	      productId: this.selectedRequest.productId,
369	      serviceTokenCount: this.selectedRequest.serviceTokenCount
370	    };
371	    this.requestFormProductIdManual = null;
372	    this.openModal('requestEdit', 'Edit request');
373	  }
374	
375	  submitRequestEdit() {
376	    if (!this.company || !this.selectedRequest) return;
377	
378	    const productId = this.requestForm.productId;
379	    if (!productId || productId <= 0) {
380	      this.modalError = 'Please select a valid Product Id.';
381	      return;
382	    }
383	
384	    if (!this.requestForm.serviceTokenCount || this.requestForm.serviceTokenCount <= 0) {
385	      this.modalError = 'Please enter a valid Service Token Count.';
386	      return;
387	    }
388	
389	    const dto: RequestDto = {
390	      companyId: this.company.id,
391	      productId,
392	      serviceTokenCount: this.requestForm.serviceTokenCount
393	    };
394	
395	    this.modalLoading = true;
396	    this.modalError = '';
397	
398	    this.requestApi.update(this.selectedRequest.id, this.selectedRequest.rowVersion, dto).subscribe({
399	      next: _ => {
400	        this.modalLoading = false;
401	        this.closeModal();
402	        this.loadRequests(true);
403	        this.toast.success('Request updated successfully.');
404	      },
405	      error: err => {
406	        this.modalLoading = false;
407	
408	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
409	        this.toast.error(message);
410	      }
411	    });
412	  }
413	
414	  async onRequestDelete() {
415	    if (!this.selectedRequest) return;
416	
417	    const confirmed = await this.dialog.confirm({
418	      title: 'Delete Request',
419	      message: `Are you sure you want to delete request #${this.selectedRequest.id}? This action cannot be undone.`,
420	      confirmText: 'Delete',
421	      type: 'danger'
422	    });
423	    if (!confirmed) return;
424	
425	    this.requestsLoading = true;
426	
427	    this.requestApi.delete(this.selectedRequest.id, this.selectedRequest.rowVersion).subscribe({
428	      next: _ => {
429	        this.requestsLoading = false;
430	        this.selectedRequest = null;
431	        this.loadRequests(true);
432	        this.toast.success('Request deleted successfully.');
433	      },
434	      error: err => {
435	        this.requestsLoading = false;
436	
437	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
438	        this.toast.error(message);
439	      }
440	    });
441	  }
442	
443	  // Row-level workflow actions (per request record)
444	  authorizeRequestRow(r: Request, event?: Event) {
445	    event?.stopPropagation();
446	    if (Number(r.status) !== RequestStatus.Created) return;
447	
448	    this.requestsLoading = true;
449	
450	    this.requestApi.authorize(r.id, r.rowVersion).subscribe({
451	      next: updated => {
452	        this.requestsLoading = false;
453	        this.patchRequestInList(updated);
454	        this.toast.success('Request authorized.');
455	      },
456	      error: err => {
457	        console.error(err);
458	        this.requestsLoading = false;
459	        
460	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
461	        this.toast.error(message);
462	      }
463	    });
464	  }
465	
466	  deauthorizeRequestRow(r: Request, event?: Event) {
467	    event?.stopPropagation();
468	    if (Number(r.status) !== RequestStatus.Authorised) return;
469	
470	    this.requestsLoading = true;
471	
472	    this.requestApi.deauthorize(r.id, r.rowVersion).subscribe({
473	      next: updated => {
474	        this.requestsLoading = false;
475	        this.patchRequestInList(updated);
476	        this.toast.success('Request deauthorized.');
477	      },
478	      error: err => {
479	        console.error(err);
480	        this.requestsLoading = false;
481	
482	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
483	        this.toast.error(message);
484	      }
485	    });
486	  }
487	
488	  private patchRequestInList(updated: Request | null | undefined) {
489	    // Some backend actions may return an empty body (null) even though the request was updated.
490	    // In that case, fall back to reloading the list instead of crashing the UI.
491	    if (!updated || (updated as any).id == null) {
492	      this.loadRequests();
493	      return;
494	    }
495	
496	    // Defensive: ensure there are no null items in the local list.
497	    this.requests = (this.requests ?? []).filter((x): x is Request => !!x && (x as any).id != null);
498	
499	    const idx = this.requests.findIndex(x => x.id === updated.id);
500	    if (idx >= 0) {
501	      this.requests[idx] = updated;
502	    } else {
503	      this.requests = [updated, ...this.requests];
504	    }
505	
506	    if (this.selectedRequest?.id === updated.id) {
507	      this.selectedRequest = updated;
508	    }
509	  }
510	
511	  // -----------------------------
512	  // Products
513	  // -----------------------------
514	  reloadProducts(silent = false) {
515	    if (!this.company) return;
516	
517	    this.productSkip = 0;
518	    this.products = [];
519	    this.selectedProduct = null;
520	    this.loadProductsPage(true, silent);
521	  }
522	
523	  loadProductsPage(resetSelection: boolean = false, silent = false) {
524	    if (!this.company) return;
525	
526	    if (resetSelection) this.selectedProduct = null;
527	    this.productsLoading = true;
528	
529	    this.productApi.getAll(this.productSkip, this.productTake, this.productSearch || null).subscribe({
530	      next: data => {
531	        const all = data ?? [];
532	        const mine = all.filter(p => p.companyId === this.company!.id);
533	
534	        // Append while avoiding duplicates by id (in case of server-side ordering changes)
535	        const existing = new Map(this.products.map(p => [p.id, p]));
536	        for (const p of mine) existing.set(p.id, p);
537	
538	        this.products = Array.from(existing.values()).sort((a, b) => a.id - b.id);
539	        this.productsLoading = false;
540	      },
541	      error: err => {
542	        console.error(err);
543	        this.productsLoading = false;
544	        if (!silent) {
545	          this.toast.errorWithRetry(
546	            'Failed to load products. Please check your connection.',
547	            () => this.loadProductsPage(false)
548	          );
549	        }
550	      }
551	    });
552	  }
553	
554	  loadMoreProducts() {
555	    this.productSkip += this.productTake;
556	    this.loadProductsPage(false);
557	  }
558	
559	  selectProduct(p: Product) {
560	    this.selectedProduct = p;
561	  }
562	
563	  onProductView() {
564	    if (!this.selectedProduct) return;
565	
566	    this.openModal('productView', 'Product details');
567	    this.modalLoading = true;
568	
569	    this.productApi.getById(this.selectedProduct.id).subscribe({
570	      next: prod => {
571	        this.modalProduct = prod;
572	        this.modalLoading = false;
573	      },
574	      error: err => {
575	        console.error(err);
576	        this.modalLoading = false;
577	        this.closeModal();
578	
579	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
580	        this.toast.error(message);
581	      }
582	    });
583	  }
584	
585	  onProductAdd() {
586	    if (!this.company) return;
587	
588	    this.productForm = {
589	      id: 0,
590	      companyId: this.company.id,
591	      name: '',
592	      serviceCount: 0,
593	      price: 0,
594	      term: null,
595	      scheduleType: { periodType: SchedulePeriodType.None, periodNumber: null }
596	    };
597	
598	    this.pictogramFile = null;
599	    this.pictogramPreviewUrl = null;
600	    this.pictogramExistsOnServer = false;
601	    this.openModal('productAdd', 'Add new product');
602	  }
603	
604	  onPictogramSelected(event: Event) {
605	    const input = event.target as HTMLInputElement;
606	    const file = input.files?.[0] ?? null;
607	    this.pictogramFile = file;
608	    if (file) {
609	      const reader = new FileReader();
610	      reader.onload = () => (this.pictogramPreviewUrl = reader.result as string);
611	      reader.readAsDataURL(file);
612	    } else {
613	      this.pictogramPreviewUrl = null;
614	    }
615	  }
616	
617	  submitProductAdd() {
618	    if (!this.company) return;
619	
620	    this.modalLoading = true;
621	    this.modalError = '';
622	
623	    const payload: Product = {
624	      ...this.productForm,
625	      companyId: this.company.id
626	    };
627	
628	    this.productApi.create(payload).subscribe({
629	      next: _ => {
630	        // Product created — now upload pictogram if one was selected.
631	        // We need the new product's ID, so we reload products to find it by name+companyId.
632	        if (this.pictogramFile) {
633	          this.reloadProducts(true);
634	          // Find the newly created product by reloading and matching name
635	          this.productApi.getAll(0, 200, payload.name).subscribe({
636	            next: all => {
637	              const created = all
638	                .filter(p => p.companyId === this.company!.id && p.name === payload.name)
639	                .sort((a, b) => b.id - a.id)[0];
640	
641	              if (created && this.pictogramFile) {
642	                this.productApi.addPictogram(created.id, this.pictogramFile).subscribe({
643	                  next: () => {
644	                    this.modalLoading = false;
645	                    this.closeModal();
646	                    this.reloadProducts(true);
647	                    this.toast.success('Product created successfully with pictogram.');
648	                  },
649	                  error: err => {
650	                    this.modalLoading = false;
651	                    this.closeModal();
652	                    this.reloadProducts(true);
653	                    const message = typeof err.error === 'string' ? err.error : err.error?.message;
654	                    this.toast.error(`Product created but pictogram upload failed: ${message}`);
655	                  }
656	                });
657	              } else {
658	                this.modalLoading = false;
659	                this.closeModal();
660	                this.reloadProducts(true);
661	                this.toast.success('Product created successfully.');
662	              }
663	            },
664	            error: () => {
665	              this.modalLoading = false;
666	              this.closeModal();
667	              this.reloadProducts(true);
668	              this.toast.success('Product created. Pictogram upload skipped (could not resolve new product ID).');
669	            }
670	          });
671	        } else {
672	          this.modalLoading = false;
673	          this.closeModal();
674	          this.reloadProducts(true);
675	          this.toast.success('Product created successfully.');
676	        }
677	      },
678	      error: err => {
679	        console.error(err);
680	        this.modalLoading = false;
681	        const message = typeof err.error === 'string' ? err.error : err.error?.message;
682	        this.toast.error(message);
683	      }
684	    });
685	  }
686	
687	  onProductEdit() {
688	    if (!this.selectedProduct) return;
689	    this.openProductEdit(this.selectedProduct.id);
690	  }
691	
692	  private openProductEdit(productId: number) {
