    const m = isApiHost ? url.pathname.match(/^\/api\/(.+)$/) : null;
    if (!m) { blocked.push(`${method} ${url.origin}${url.pathname}`); return route.abort('blockedbyclient'); }
    if (method === 'OPTIONS') return route.fulfill({ status: 204, headers: cors });
